                            status?: string;
                            sub_status?: unknown;
                            /** @example 46adcbc0-aa26-4867-a4e7-28a5ad9100ae */
                            vaulted_token?: string;
                            callback_url?: unknown;
                            action?: unknown;
                            redirect_url?: unknown;
